## Summary
- improve temporary mode toggle detection with text content and aria attributes
- persist toggle state using siteTempMode() with isOn fallback

## Testing
- `node --check contentScript.js`
- `node - <<'NODE'
const LABELS = { tempToggleOff: [/turn off temporary/i, /выключить временн/i] };

global.document = { body: { dataset: {} }, cookie: '' };
function siteTempMode() {
  const body = document.body;
  if (body && body.dataset) {
    const attr = body.dataset.temporaryMode;
    if (attr === 'true' || attr === 'enabled') return true;
    if (attr === 'false' || attr === 'disabled') return false;
  }
  const match = document.cookie.match(/(?:^|; )oai-temporary-mode=(true|false)/);
  if (match) return match[1] === 'true';
  return null;
}
function isOn(el) {
  const site = siteTempMode();
  if (typeof site === 'boolean') return site;
  const label = el.getAttribute('aria-label') || el.textContent || '';
  return LABELS.tempToggleOff.some(rx => rx.test(label)) ||
         el.getAttribute('aria-pressed') === 'true' ||
         el.getAttribute('aria-checked') === 'true' ||
         el.classList.contains('active') ||
         (el.checked === true);
}
function storeState(on) { console.log('сохраняем состояние', on); }

// Simulate click handler with siteTempMode() fallback
const el = {
  getAttribute(name) { return this.attrs[name]; },
  textContent: '',
  classList: { contains() { return false; } },
  checked: false,
  attrs: { 'aria-label': 'выключить временный чат' }
};
setTimeout(() => storeState(siteTempMode() ?? isOn(el)), 0);
setTimeout(() => {}, 10); // allow timeout to run
NODE`
